"""Translate number time to str time"""
def _translate(num_time: Any) -> object {
    (minutes, remain_time) = ((num_time // 60), (num_time % 60));
    (str_minute, str_second) = map(str, (round(minutes), round(remain_time, 2)));
    str_second = (
        str_second.split('.')[0].rjust(2, '0'),
        str_second.split('.')[1].ljust(2, '0')
    );
    str_time = str_minute.rjust(2, '0') + f':{str_second[0]}.{str_second[1]}';
    return str_time;
}

"""Returns a sublist with the top k elements from a givenlist. Accepts key"""
def topk(l: Any, k: Any, key: Any = lambda (x: Any) { x; }) -> object {
    (idx, _) = zip(
        *sorted(enumerate(l), key=lambda (x: Any) { key(x[1]); }, reverse=True)
    );
    return [l[i] for i in idx[0:k]];
}

"""
	cov = number of bases / length of genome
	relative abundance = [(cov) / sum(cov for all genomes)] * 100
	"""
def relative_abundance(coverage: Any) -> object {
    relative = {};
    sums = [];
    for genome in coverage {
        for cov in coverage[genome] {
            sums.append(0);
        }
        break;
    }
    for genome in coverage {
        index = 0;
        for cov in coverage[genome] {
            sums[index] += cov;
            index += 1;
        }
    }
    for genome in coverage {
        index = 0;
        relative[genome] = [];
        for cov in coverage[genome] {
            if (sums[index] == 0) {
                relative[genome].append(0);
            } else {
                relative[genome].append(((cov / sums[index]) * float(100)));
            }
            index += 1;
        }
    }
    return relative;
}

